import{_ as i,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph code walk-through: OSD (async) recovery","description":"","frontmatter":{"title":"Ceph code walk-through: OSD (async) recovery","date":"2018-07-31T00:00:00.000Z","updated":"2018-08-01T00:00:00.000Z","tags":["Ceph","异步恢复","OSD","分布式存储","CRUSH算法","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_code_walk-through_-_OSD_async_recovery.md","filePath":"posts/2018/Ceph_code_walk-through_-_OSD_async_recovery.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Ceph_code_walk-through_-_OSD_async_recovery.md"};function s(_,l,a,n,c,p){return e(),t("div",null,[...l[0]||(l[0]=[o("<p>Ceph分布式存储系统中，传统的对象恢复过程是同步的，这会导致写操作被阻塞，从而影响集群的可用性。为了解决这个问题，Ceph团队引入了一种名为异步恢复的新机制。</p><p><strong>会议内容概述</strong>：</p><ul><li><strong>会议背景与动机</strong>： 同步恢复机制会阻塞写操作，影响集群可用性。异步恢复机制旨在后台恢复对象，而不会阻塞写操作。</li><li><strong>异步恢复的关键概念</strong>： <ul><li>目标：恢复仅在非活跃OSD上缺失的对象。</li><li>选择标准：基于日志差异、对象大小和恢复成本等因素。</li><li>最小PG日志条目：用于确定是否允许同步恢复的阈值。</li><li>保持主副本大小：只有当有足够的主副本可用时，才考虑同步恢复。</li></ul></li><li><strong>异步恢复的代码实现</strong>： <ul><li>选择活跃OSD：修改了选择活跃OSD的算法，使其能够识别异步恢复目标。</li><li>处理写操作：修改了写操作的代码，使其在异步恢复目标上不会阻塞。</li><li>更新元数据：在异步恢复过程中，需要更新元数据结构，以确保恢复的准确性。</li></ul></li><li><strong>恢复操作</strong>： <ul><li>启动恢复操作：使用<code>PGRecovery::run</code>函数启动恢复操作。</li><li>恢复副本：恢复操作会尝试从副本恢复丢失的对象。</li></ul></li><li><strong>讨论与后续行动</strong>： <ul><li>讨论了异步恢复的代码实现细节，并提出了改进建议。</li><li>团队计划制作一个流程图，以更直观地展示异步恢复的工作原理。</li><li>团队将根据讨论结果进一步改进异步恢复机制。</li></ul></li></ul><p><strong>关键词</strong>：</p><ul><li>异步恢复</li><li>同步恢复</li><li>非活跃OSD</li><li>日志差异</li><li>恢复成本</li><li>选择活跃OSD</li><li>写操作</li><li>元数据</li><li>恢复操作</li><li>副本</li><li>Ceph</li><li>分布式存储</li><li>CRUSH算法</li><li>性能优化</li></ul>",5)])])}const h=i(r,[["render",s]]);export{d as __pageData,h as default};
